"use client";

interface StockRow {
  _id: string;
  name: string;
  voucher: "Purchase" | "Sale";
  quantity: number;
  unit: string;
  price: number;
  entryNo: string;
  date: string;
}

interface Props {
  title: string;
  subtitle: string;
  rows: StockRow[];
  type: "Purchase" | "Sale";
}

export default function StockHistoryTable({
  title,
  subtitle,
  rows,
  type,
}: Props) {
  const isPurchase = type === "Purchase";

  const accent = isPurchase ? "emerald" : "rose";
  const bgTint = isPurchase
    ? "bg-emerald-500/5 hover:bg-emerald-500/10"
    : "bg-rose-500/5 hover:bg-rose-500/10";
  const valueColor = isPurchase
    ? "text-emerald-400"
    : "text-rose-400";

  return (
    <div
      className={`rounded-xl border border-white/10 transition-colors ${bgTint}`}
    >
      {/* HEADER */}
      <div className="px-6 py-4 border-b border-white/10 bg-white/5 rounded-t-xl">
        <h3
          className={`font-semibold ${isPurchase ? "text-emerald-400" : "text-rose-400"}`}
        >
          {title}
        </h3>
        <p className="text-xs text-muted">
          {subtitle}
        </p>
      </div>

      {rows.length === 0 ? (
        <p className="px-6 py-8 text-sm text-muted">
          No {type.toLowerCase()} records found.
        </p>
      ) : (
        <div className="divide-y divide-white/5">
          {/* TABLE HEADER */}
          <div className="grid grid-cols-12 px-6 py-3 text-xs font-medium text-muted bg-white/5">
            <div className="col-span-3">Product</div>
            <div className="col-span-2 text-right">Qty</div>
            <div className="col-span-2 text-right">Rate</div>
            <div className="col-span-2 text-right">Value</div>
            <div className="col-span-3 text-center">Entry / Date</div>
          </div>

          {/* ROWS */}
          {rows.map(row => (
            <div
              key={row._id}
              className="grid grid-cols-12 gap-3 px-6 py-4 text-sm bg-transparent hover:bg-white/5 transition"
            >
              {/* Product */}
              <div className="col-span-3">
                <div className="font-medium text-foreground">
                  {row.name}
                </div>
                <div className="text-xs text-muted">
                  {row.unit}
                </div>
              </div>

              {/* Qty */}
              <div className="col-span-2 text-right font-medium text-foreground">
                {row.quantity}
              </div>

              {/* Rate */}
              <div className="col-span-2 text-right text-muted">
                ₹{row.price}
              </div>

              {/* Value */}
              <div
                className={`col-span-2 text-right font-semibold ${valueColor}`}
              >
                ₹{row.quantity * row.price}
              </div>

              {/* Entry */}
              <div className="col-span-3 text-xs text-center text-muted">
                <div className="font-medium">
                  {row.entryNo}
                </div>
                <div>
                  {new Date(row.date).toLocaleDateString()}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
